begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not has_function_privilege('anon','api.run_arrive_and_advance(uuid,uuid,integer,text,jsonb,text,uuid,text)','execute'),'anonymous visitors cannot confirm an arrival');
select ok(not has_function_privilege('authenticated','api.portal_print_access(uuid,uuid,text,integer,text,bytea,bytea)','execute'),'print material is server-only');
select ok(not has_function_privilege('authenticated','api.redesign_arrival_backfill(uuid,text,uuid[],boolean)','execute'),'backfill requires a controlled operator');
select ok(not has_table_privilege('authenticated','app_private.run_stop_arrivals','insert'),'clients cannot invent presence');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='app_private' and c.relname in ('run_stop_arrivals','portal_print_material','participant_tutorials','community_acknowledgements','portal_thanks','poortenboek_tutorials','poortenboek_chapter_reads') and c.relrowsecurity),7::bigint,'all seven new private tables have RLS');
create function pg_temp.domain_fingerprint() returns jsonb language plpgsql as $$
declare item record; result jsonb:='{}'; fingerprint text;
begin
 for item in select tablename from pg_tables where schemaname='app_private' order by tablename loop
  execute format('select md5(coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text)::text,''[]'')) from app_private.%I t',item.tablename) into fingerprint;
  result:=result||jsonb_build_object(item.tablename,fingerprint);
 end loop;
 return result;
end $$;
create temp table redesign_baseline as select pg_temp.domain_fingerprint() fingerprint;
create temp table redesign_reports(scenario text,report jsonb);
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into redesign_reports select name,api.redesign_rehearsal('duindorp-halloween-2026',name) from unnest(array['start','arrival','inclusive','wrong','duplicate','closed','manual','offline','stale','early','part-departure','finale']) name;
select ok((report->>'passed')::boolean,'SQL rehearsal: '||scenario) from redesign_reports;
select ok((step->>'passed')::boolean,scenario||': '||(step->>'title')) from redesign_reports cross join lateral jsonb_array_elements(report->'steps') step;
select is((select sum(jsonb_array_length(report->'steps')) from redesign_reports),46::bigint,'twelve scenarios execute 46 measured checkpoints');
select is(pg_temp.domain_fingerprint(),(select fingerprint from redesign_baseline),'all private rows, IDs, relationships and histories survive the rehearsal unchanged');
select ok(not exists(select 1 from app_private.events where slug like 'rehearsal-%'),'no rehearsal event remains');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select api.redesign_rehearsal('duindorp-halloween-2026','arrival')$$,'42501','NOT_AUTHORIZED','a participant cannot run the organizer rehearsal');
select is(api.participant_guidance('duindorp-halloween-2026')->>'acknowledgedDay',null::text,'new account day requires acknowledgment');
select is(api.participant_guidance('duindorp-halloween-2026','acknowledge')->>'acknowledgedDay',((now() at time zone 'Europe/Amsterdam')::date)::text,'daily acknowledgment uses Amsterdam time');
select lives_ok($$select api.participant_guidance('duindorp-halloween-2026','acknowledge')$$,'repeated acknowledgment is idempotent');
select is((select count(*) from app_private.community_acknowledgements where user_id='a0000000-0000-0000-0000-000000000001'),1::bigint,'one daily account/event record');
select throws_ok($$select api.participant_guidance('duindorp-halloween-2026','tutorial','parent','{"version":1,"index":13,"returnPath":"/omgeving"}')$$,'P0001','TUTORIAL_STEP_REQUIRED','a client cannot jump thirteen tutorial steps');
select throws_ok($$select api.participant_guidance('duindorp-halloween-2026','tutorial','house','{"version":1,"index":1,"returnPath":"/omgeving"}')$$,'42501','NOT_AUTHORIZED','a parent cannot claim a house role');
do $$begin for i in 1..13 loop perform api.participant_guidance('duindorp-halloween-2026','tutorial','parent',jsonb_build_object('version',1,'index',i,'returnPath','/omgeving/meeloper/route?poort=kept'));end loop;end$$;
select lives_ok($$select api.participant_guidance('duindorp-halloween-2026','tutorial','parent','{"version":1,"index":13,"completed":true,"returnPath":"/omgeving/meeloper/route?poort=kept"}')$$,'sequential 14-step tutorial completes');
select is(api.participant_guidance('duindorp-halloween-2026')->'completed'->>'parent','1','tutorial completion is account-bound');
select is((timestamptz '2026-10-24 22:30:00Z' at time zone 'Europe/Amsterdam')::date,date '2026-10-25','summer-time midnight uses the new local day');
select is((timestamptz '2026-10-25 23:30:00Z' at time zone 'Europe/Amsterdam')::date,date '2026-10-26','winter-time midnight uses the new local day');
create temp table redesign_child as select rc.child_id,rc.event_id from app_private.registration_children rc join app_private.registrations r on r.id=rc.registration_id where r.reference='FIXTURE-1' limit 1;
insert into app_private.poortenboek_codes(event_id,child_id,code_digest,ciphertext) select event_id,child_id,repeat('4',64),repeat('encrypted',8) from redesign_child;
insert into app_private.poortenboek_sessions(code_id,token_hash) select id,repeat('5',64) from app_private.poortenboek_codes where code_digest=repeat('4',64);
select lives_ok($$select api.poortenboek_child_action(repeat('5',64),'snapshot')$$,'an existing child session still opens its own book');
select throws_ok($$select api.poortenboek_child_action(repeat('5',64),'chapter_read','{"chapter":6}')$$,'P0001','CHAPTER_LOCKED','a direct request cannot mark a sleeping chapter read');
select throws_ok($$select api.poortenboek_child_action(repeat('5',64),'tutorial','{"version":1,"step":8,"completed":true}')$$,'P0001','TUTORIAL_STEP_REQUIRED','a child cannot forge nine completed steps');
do $$begin for i in 1..8 loop perform api.poortenboek_child_action(repeat('5',64),'tutorial',jsonb_build_object('version',1,'step',i));end loop;end$$;
select lives_ok($$select api.poortenboek_child_action(repeat('5',64),'tutorial','{"version":1,"step":8,"completed":true}')$$,'a nine-step child tutorial completes');
select is((select count(*) from app_private.poortenboek_tutorials where completed_at is not null),1::bigint,'only this child is completed');
select lives_ok($$select api.poortenboek_child_action(repeat('5',64),'chapter_read','{"chapter":1}')$$,'an unlocked chapter can be marked read');
select lives_ok($$select api.poortenboek_child_action(repeat('5',64),'chapter_read','{"chapter":1}')$$,'rereading is idempotent');
select is((select count(*) from app_private.poortenboek_chapter_reads),1::bigint,'one read record per child/chapter');
update app_private.events set phase='completed' where id=(select event_id from redesign_child);
select is(api.poortenboek_child_action(repeat('5',64),'snapshot')->'journey'->>'complete','false','event closure does not invent a personal finale');
select ok(not exists(select 1 from jsonb_array_elements(api.poortenboek_child_action(repeat('5',64),'snapshot')->'journey'->'chapters') c where c->>'chapter'='6'),'the final chapter is not fabricated by the event phase');
select is(api.portal_print_access('e0000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001')->>'legacy','true','hash-only legacy print material is honestly reported');
select is((select count(*) from app_private.portal_credentials where portal_id='12000000-0000-0000-0000-000000000001' and revoked_at is null),1::bigint,'reading a poster does not rotate credentials');
select is(api.redesign_arrival_backfill('f0000000-0000-0000-0000-000000000001','duindorp-halloween-2026')->>'applied','false','backfill defaults to a read-only preview');
select throws_ok($$select api.redesign_arrival_backfill('f0000000-0000-0000-0000-000000000001','duindorp-halloween-2026','{}',true)$$,'P0001','BOUNDED_REVIEW_REQUIRED','backfill requires an explicitly reviewed bounded batch');
select * from finish();
rollback;
